import subprocess,json,pathlib,time
root=pathlib.Path(__file__).resolve().parents[2];log=(root/'evidence/logs/offline-http.log').open('w')
def run(*args,js=None):
    cmd=['agent-browser','--session','strata',*map(str,args)];log.write('$ '+' '.join(cmd)+'\n');log.flush();r=subprocess.run(cmd,input=js,text=True,capture_output=True);log.write(r.stdout+r.stderr+'\n');log.flush();assert r.returncode==0,r.stderr;return r.stdout.strip()
def ev(js):return json.loads(run('eval','--stdin',js=js))
hold=subprocess.Popen(['node',str(root/'evidence/tests/native-input.cjs'),'network_hold'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True);ready=hold.stdout.readline();log.write('Cache disabled on active target: '+ready);assert json.loads(ready)['ready'];run('console','--clear');run('errors','--clear');run('network','requests','--clear');run('network','har','start')
run('open','http://127.0.0.1:8080/index.html');run('set','viewport','1280','800','1');run('wait','--fn','window.strata && window.strata.diagnostics().time >= 8');run('click','#pause');diagnostics=ev('window.strata.diagnostics()');assert diagnostics['eroded']>0 and diagnostics['change']>.01 and diagnostics['glError']==0;print('PASS Offline local HTTP renders and evolves real terrain',flush=True);run('screenshot',root/'evidence/screenshots/final-desktop-evolved.png')
resources=ev("performance.getEntriesByType('resource').map(e=>e.name)");assert all(url.startswith('http://127.0.0.1:8080/') or url.startswith('data:') or url.startswith('blob:') for url in resources);print('PASS No external runtime resources',resources,flush=True);run('network','requests');run('network','har','stop',root/'evidence/logs/offline-http.har')
console=run('console');errors=run('errors');assert not console and not errors;print('PASS No console messages or uncaught errors in fresh HTTP workflow',flush=True);(root/'evidence/logs/offline-http-results.json').write_text(json.dumps({'status':'pass','diagnostics':diagnostics,'resources':resources,'console':console,'errors':errors,'cacheDisabled':True,'externalProxy':'http://127.0.0.1:9'},indent=2))
# Capture a clean narrow view after allowing the real controls drawer transition.
run('set','viewport','390','844','1');run('click','#home');run('screenshot',root/'evidence/screenshots/final-mobile.png');run('click','#openPanel');run('wait','--fn',"Math.abs(document.getElementById('sidebar').getBoundingClientRect().left)<1");run('screenshot',root/'evidence/screenshots/final-mobile-controls.png');run('click','#closePanel');run('wait','--fn',"document.getElementById('sidebar').getBoundingClientRect().right<=0");run('set','viewport','1280','800','1');run('click','#home');hold.stdin.close();hold.wait(timeout=10);log.write(hold.stdout.read()+hold.stderr.read());print('Offline HTTP workflow complete',flush=True)
